cat > /tmp/probe2.go <<'EOF'
package main

import (
	"fmt"
	"strings"
)

func main() {
	a := "(€10.00)"
	// original: rune-count based
	al := 0
	for range a {
		al++
	}
	orig := strings.Repeat(" ", 13-al) + a
	// fmt approach
	f := fmt.Sprintf("%*s", 13, a)
	fmt.Printf("orig len(runes)=%d bytes=%d: [%s]\n", runeLen(orig), len(orig), orig)
	fmt.Printf("fmt  len(runes)=%d bytes=%d: [%s]\n", runeLen(f), len(f), f)
	fmt.Printf("equal=%v\n", orig == f)
}

func runeLen(s string) int {
	n := 0
	for range s {
		n++
	}
	return n
}
EOF
