package ledger

import "testing"

func TestDifferential(t *testing.T) {
	currencies := []string{"USD", "EUR"}
	locales := []string{"en-US", "nl-NL"}
	dates := []string{"2015-01-01", "2015-12-31", "1999-03-07"}
	descs := []string{"", "Buy present", "a", "Freude schoner Gotterfunken", "x"}
	changes := []int{0, 1, -1, 1000, -1000, 12345, -12345, 123456, -123456, 1000000, -987654321, 42}
	for _, cur := range currencies {
		for _, loc := range locales {
			for _, d := range dates {
				for _, de := range descs {
					for _, c := range changes {
						got, gerr := FormatLedger(cur, loc, []Entry{{d, de, c}})
						want, werr := origFormatLedger(cur, loc, []Entry{{d, de, c}})
						if (gerr == nil) != (werr == nil) || got != want {
							t.Fatalf("mismatch cur=%s loc=%s d=%s de=%q c=%d\n got=%q gerr=%v\nwant=%q werr=%v", cur, loc, d, de, c, got, gerr, want, werr)
						}
					}
				}
			}
		}
	}
	// multi-entry ordering
	entries := []Entry{{"2015-01-01", "b", 5}, {"2015-01-01", "a", -5}, {"2015-01-01", "a", 5}, {"2014-12-31", "z", 0}}
	got, _ := FormatLedger("USD", "nl-NL", entries)
	want, _ := origFormatLedger("USD", "nl-NL", entries)
	if got != want {
		t.Fatalf("multi mismatch:\n got=%q\nwant=%q", got, want)
	}
}
EOF
